WITH valid AS (SELECT *, ROUND(budget, 1) AS budget_rounded FROM departments WHERE location IS NOT NULL AND location IS DISTINCT FROM 'New York'), with_windows AS (SELECT *, SUM(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_budget, PERCENT_RANK() OVER (ORDER BY budget_rounded DESC) AS budget_rounded_percent_rank FROM valid), latest_match AS (SELECT s.id, s.location, s.budget, latest.employee_job_title, latest.salary FROM with_windows s LEFT JOIN LATERAL (SELECT c.job_title AS employee_job_title, c.salary FROM employees c WHERE c.dept_id = s.id ORDER BY c.hire_date DESC, c.id DESC LIMIT 1) latest ON TRUE), not_flagged AS (SELECT s.* FROM latest_match s WHERE NOT EXISTS (SELECT 1 FROM employees ch WHERE ch.dept_id = s.id AND ch.salary <= 85000)) SELECT id, location, budget, employee_job_title, salary FROM not_flagged ORDER BY employee_job_title DESC NULLS LAST
